import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework.DNWyyI0w.js";const u=JSON.parse('{"title":"Credits, Usage & Spend Limits","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/credits-and-usage.md","filePath":"concepts/credits-and-usage.md"}'),o={name:"concepts/credits-and-usage.md"};function d(r,e,i,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="credits-usage-spend-limits" tabindex="-1">Credits, Usage &amp; Spend Limits <a class="header-anchor" href="#credits-usage-spend-limits" aria-label="Permalink to &quot;Credits, Usage &amp; Spend Limits&quot;">​</a></h1><p>A <strong>credit is one US dollar</strong>. The wallet is a USD balance that every settled LLM call decrements by what that call cost, and the ledger beside it is the append-only record of why. Everything on this page sits on top of metering that already exists: the run&#39;s <code>usageLog</code> records what a call spent whether or not a wallet is watching.</p><p>The platform pays for the tokens, so the wallet is the thing that actually stops work: an empty wallet halts a run before the next call is made, not after the bill arrives. While early access lasts, credits are granted rather than purchased.</p><h2 id="how-usage-is-metered" tabindex="-1">How usage is metered <a class="header-anchor" href="#how-usage-is-metered" aria-label="Permalink to &quot;How usage is metered&quot;">​</a></h2><p>Every settled LLM call produces a token record:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>inputTokens</code></td><td>Fresh input tokens</td></tr><tr><td><code>cacheReadTokens</code></td><td>Input served from cache</td></tr><tr><td><code>cacheCreationTokens</code></td><td>Input written to cache (billed at its own rate)</td></tr><tr><td><code>outputTokens</code></td><td>Generated tokens</td></tr><tr><td><code>costUsd</code></td><td>The settled price, when the provider reported one</td></tr><tr><td><code>unreported</code></td><td>The call ran but no request reported a token — zeros here are an <em>absent measurement</em>, not a measurement of zero</td></tr></tbody></table><p>The engine folds that record into the run twice: as one <code>RunUsageEntry</code> appended to <code>run.usageLog</code>, and as a running total on the participant that made the call. A call that moved tokens but carries no <code>costUsd</code> is stamped <code>unpriced</code> and counted on the participant&#39;s <code>unpricedCalls</code>, so a total can always say how much of itself was never costed. An unpriced call is never rendered as free.</p><p>Separately, each thread message carries its own settled vitals (<code>RunEventStats</code>) — tokens, wall-clock ms, context occupancy, model, and cost. Because providers bill a turn once rather than per message, a multi-message turn&#39;s cost is <em>apportioned</em> across its messages and flagged <code>costShared</code>, so the UI can say &quot;share of a turn&quot; instead of presenting an estimate as an invoice.</p><p>Three call classes are metered, all through the same accounting:</p><ul><li><strong>Run delegations and PRIME&#39;s run turns</strong> — into the run&#39;s <code>usageLog</code>, then the wallet.</li><li><strong>Main-chat turns</strong> (dashboard chat, Telegram and other channels) — straight to the wallet with ledger reason <code>chat.usage</code>.</li><li><strong>Side calls</strong> (the memory curator, and any other post-turn helper) — routed by ambient scope: inside a run they land in that run&#39;s ledger, outside one they hit the wallet. These are small per call but fire constantly, which is exactly the shape of spend that otherwise goes unnoticed.</li></ul><h2 id="the-wallet-and-the-ledger" tabindex="-1">The wallet and the ledger <a class="header-anchor" href="#the-wallet-and-the-ledger" aria-label="Permalink to &quot;The wallet and the ledger&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>memory/credits.json        ← wallet snapshot (local dev fallback only)</span></span>
<span class="line"><span>memory/credit-ledger.jsonl ← one JSON object per line, append-safe</span></span></code></pre></div><p>MongoDB is the authoritative store: <code>CreditWalletModel</code> (keyed by <code>orgId</code>) and <code>CreditLedgerModel</code>. The files above are written only when Mongo is unreachable in local development; in cloud mode a persist attempt with no DB is refused and logged rather than silently accepted.</p><p>The wallet update is an atomic aggregation-pipeline <code>$add</code> floored with <code>$max</code> at zero, upserted, with the returned document treated as authoritative. That matters with more than one instance running: a concurrent debit from another process cannot be lost to a last-writer-wins overwrite of a process-local balance.</p><p><strong>The balance can never go below zero</strong> — not by debit, not by adjustment, not by a call that costs more than what is left. A persisted legacy negative balance is normalised to zero on load.</p><p>Each ledger entry is immutable:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td>Base-36 millisecond prefix + UUID (roughly sortable, collision-resistant)</td></tr><tr><td><code>at</code></td><td>Timestamp</td></tr><tr><td><code>delta</code></td><td>What actually moved in the wallet — negative for a debit, positive for a top-up</td></tr><tr><td><code>reason</code></td><td><code>run.usage</code> · <code>chat.usage</code> · <code>topup.manual</code> · <code>adjustment</code> · <code>grant.admin</code> · <code>revoke.admin</code></td></tr><tr><td><code>runId</code></td><td>The run the debit belongs to (<code>run.usage</code> only)</td></tr><tr><td><code>actor</code></td><td>Which participant&#39;s call it was — pairs with the run&#39;s log</td></tr><tr><td><code>orgId</code> / <code>userId</code></td><td>Owning workspace and acting member (cloud)</td></tr><tr><td><code>rawCostUsd</code></td><td>The provider&#39;s raw cost <em>before</em> margin</td></tr><tr><td><code>models</code></td><td>Every model the settled call reported</td></tr><tr><td><code>balanceAfter</code></td><td>The balance once the entry was applied</td></tr></tbody></table><p><code>delta</code> and <code>rawCostUsd</code> deliberately differ when a final debit is truncated by the zero floor: <code>delta</code> describes the wallet movement, <code>rawCostUsd</code> still records the full provider cost. Between <code>runId</code> and <code>actor</code>, every line traces back to a run and from there to the exact calls that produced it.</p><p>The in-memory ledger keeps the most recent 500 entries; the API clamps a requested limit to that. The files and the database keep everything.</p><h2 id="margin" tabindex="-1">Margin <a class="header-anchor" href="#margin" aria-label="Permalink to &quot;Margin&quot;">​</a></h2><p><code>creditsMargin</code> (a system setting, default <code>1</code>, minimum <code>1</code>) multiplies <code>costUsd</code> on debit. <code>1</code> means the wallet is charged at cost; a value above <code>1</code> is a managed margin. The charged amount is rounded to six decimal places — well below the price of a single token — to stop float drift accumulating on a running balance.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>charged = round6(costUsd × max(creditsMargin, 1))</span></span></code></pre></div><p>The same margin is applied to the run cost that per-run ceilings compare against, so the ceiling and the ledger agree on what a run has spent.</p><h2 id="the-caps-that-exist" tabindex="-1">The caps that exist <a class="header-anchor" href="#the-caps-that-exist" aria-label="Permalink to &quot;The caps that exist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cap</th><th>Where it lives</th><th>Default</th><th>Effect when crossed</th></tr></thead><tbody><tr><td>Wallet balance</td><td>The workspace wallet</td><td>—</td><td><strong>Refuses</strong> new work (cloud only)</td></tr><tr><td><code>monthlyCreditBudget</code></td><td>Member limits</td><td><code>0</code> (unlimited)</td><td><strong>Refuses</strong> new work; <strong>pauses</strong> a live run</td></tr><tr><td><code>extraCreditGrant</code></td><td>Member limits</td><td><code>0</code></td><td>One-time top-up on this month&#39;s budget</td></tr><tr><td><code>perRunCostCapUsd</code></td><td>Member limits</td><td><code>0</code> (off)</td><td><strong>Pauses</strong> the run</td></tr><tr><td><code>maxConcurrentRuns</code></td><td>Member limits, then org limits</td><td><code>0</code> (member) / <code>3</code> (org)</td><td>Refuses a new run</td></tr><tr><td><code>maxEffort</code></td><td>Member limits</td><td><code>&#39;&#39;</code> (none)</td><td><strong>Clamps</strong> the request down — never rejects</td></tr><tr><td><code>turnMaxCostUsd</code></td><td>System settings</td><td><code>5</code></td><td><strong>Pauses</strong> the run after one over-budget call</td></tr><tr><td><code>runCostAlertUsd</code></td><td>System settings</td><td><code>0</code> (off)</td><td>A global per-run ceiling that <strong>pauses</strong> the run</td></tr></tbody></table><p>Two things to note. Effort is the only dial that degrades rather than stopping: a member capped at <code>medium</code> who asks for <code>high</code> silently gets <code>medium</code>. And <code>turnMaxCostUsd</code> is enforced against the price <em>Saidi settled on</em>, which is why it still holds on a custom endpoint where the SDK&#39;s own budget parameter would be denominated in a rate table the ledger does not use.</p><h2 id="where-the-gates-fire" tabindex="-1">Where the gates fire <a class="header-anchor" href="#where-the-gates-fire" aria-label="Permalink to &quot;Where the gates fire&quot;">​</a></h2><p><strong>Before a run starts.</strong> In order: the workspace must be active and not suspended; the wallet must be non-empty; the member&#39;s monthly budget must have room; the member and the org must be under their concurrency caps. Any failure throws a human-readable error the caller surfaces — a route, a PRIME tool, a cron, a reflex, a Telegram message. On success the run start is counted on the member&#39;s monthly counter.</p><p><strong>Before every billable call.</strong> A lighter check runs on the hot paths — main chat, existing runs, channels, nested agent calls. It looks at spend eligibility only: the wallet, and the acting member&#39;s monthly budget. Membership caching is ~30 seconds so this does not add a database query per tool call.</p><p>This check <strong>fails closed</strong>. A missing membership means the person was removed and may not keep spending. A transient database error blocks spend with <code>Usage checks are temporarily unavailable — please retry in a moment.</code> rather than letting an unhandled rejection escape a fire-and-forget path. System automations and platform superadmins bypass it.</p><p><strong>After every settled call.</strong> The debit lands, then the wallet is re-checked, then the member&#39;s per-run and monthly caps are evaluated asynchronously. A crossed cap pauses the run.</p><h2 id="what-a-blocked-run-actually-does" tabindex="-1">What a blocked run actually does <a class="header-anchor" href="#what-a-blocked-run-actually-does" aria-label="Permalink to &quot;What a blocked run actually does&quot;">​</a></h2><p>The pause path is deliberately the same shape as every other budget stop: a <code>SYSTEM</code> event is appended to the run thread with the reason, and the run is moved to <code>paused</code> — <strong>never cancelled</strong>. Pausing preserves the resumable-run semantics described in <a href="/docs/concepts/runs">Runs</a>: the plan, the branch, the sessions and the in-flight record all survive, and resuming picks up where it stopped.</p><p>The model is told too, and told plainly. Every delegation tool — PRIME&#39;s <code>delegate</code> and <code>delegate_batch</code>, a lead&#39;s <code>delegate_to_specialist</code> / <code>delegate_to_specialists</code>, <code>delegate_to_project</code>, and the <code>ask</code> path — checks the gate <em>before</em> dispatching and, when it is blocked, returns the block text as an <strong>error tool result</strong>. The model does not get a generic &quot;something failed&quot;; it gets one of:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Insufficient credits: the wallet balance is $0.00. Ask your workspace owner to</span></span>
<span class="line"><span>add credits to continue.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Your monthly usage budget ($25.00) is used up — it resets next month, or an</span></span>
<span class="line"><span>admin can raise it.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are no longer a member of this workspace.</span></span></code></pre></div><p>Mid-run pauses, which happen after a debit rather than before a dispatch, produce their own wording:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run paused: its cost reached your per-run cap of $10.00. An admin can raise the</span></span>
<span class="line"><span>cap, then resume the run.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run paused: your monthly usage budget ($25.00) is used up — it resets next</span></span>
<span class="line"><span>month, or an admin can raise it.</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run paused: its owner is no longer a member of this workspace — an admin can</span></span>
<span class="line"><span>remove or reassign it.</span></span></code></pre></div><p>And the per-call ceiling, which names the setting so the fix is obvious:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;actor&gt; settled at $6.2100 for one call, over the $5 per-turn ceiling. Paused —</span></span>
<span class="line"><span>raise CALL COST CEILING in Settings → Costs &amp; Limits, or resume to continue.</span></span></code></pre></div><p>A workspace with a single member has no per-member cap to apply, but a runaway run can still burn tokens. <code>runCostAlertUsd</code> doubles as a real global per-run pause ceiling there. It is opt-in — <code>0</code> means off, and local behaviour is unchanged until you set it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run paused: its cost reached the per-run ceiling of $12.00 (runCostAlertUsd).</span></span>
<span class="line"><span>Raise the ceiling in Settings, then resume the run.</span></span></code></pre></div><p>Metering itself never breaks work. Debiting, member counters and the mid-run cap evaluation are all best-effort and swallow their own errors — bookkeeping must not be the reason a run fails.</p><h2 id="reading-a-balance" tabindex="-1">Reading a balance <a class="header-anchor" href="#reading-a-balance" aria-label="Permalink to &quot;Reading a balance&quot;">​</a></h2><p><code>GET /api/credits</code> returns what the <em>asking member</em> can still spend, which is not necessarily the wallet balance. A configured monthly budget is a hard ceiling even when the shared wallet holds more:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>available = min(walletBalance, (monthlyCreditBudget + extraCreditGrant) − spentThisMonth)</span></span></code></pre></div><p>With no monthly budget configured, the wallet is the only ceiling and the response reports <code>limited: false</code>.</p><p><code>GET /api/credits/usage?limit=N</code> returns the wallet plus the detailed ledger, and requires the <code>billing.view</code> or <code>usage.viewOrg</code> permission. Both endpoints are cloud only. After every debit or top-up a wallet observer notifies dashboards with an amount-free invalidation, and each client re-fetches its own scoped balance.</p><h2 id="topping-up-and-raising-a-cap" tabindex="-1">Topping up and raising a cap <a class="header-anchor" href="#topping-up-and-raising-a-cap" aria-label="Permalink to &quot;Topping up and raising a cap&quot;">​</a></h2><p><strong>Adding credits</strong> is a superadmin action on the platform plane:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/admin/orgs/:id/credits</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;amount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">250</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>A positive amount is a grant (ledger reason <code>grant.admin</code>), a negative amount a revocation (<code>revoke.admin</code>). The amount must be non-zero and no larger than 100,000 in magnitude, and the acting superadmin&#39;s user id is recorded on the entry. The response returns the new balance. This is the manual-billing path; the store&#39;s older <code>topUp</code> method is retained only for migrations and store-level tests.</p><p><strong>Raising a member&#39;s cap</strong> means editing that member&#39;s limits — <code>monthlyCreditBudget</code>, <code>extraCreditGrant</code>, <code>perRunCostCapUsd</code>, <code>maxEffort</code>, <code>maxConcurrentRuns</code>. <code>extraCreditGrant</code> is the right dial for &quot;give this person more room <em>this month</em>&quot; without permanently moving their budget. Governance records are cached for about 30 seconds and the cache is invalidated on an admin edit, so a change applies promptly rather than at the next cache expiry.</p><p><strong>Operator-wide dials</strong> — <code>creditsMargin</code>, <code>turnMaxCostUsd</code>, <code>runCostAlertUsd</code> — live in system settings; see <a href="/docs/reference/settings">Settings</a>.</p><p>After raising whatever stopped it, resume the paused run. Nothing needs re-planning: the run was paused, not cancelled.</p><p>See also: <a href="/docs/guides/guardrails">Approval &amp; Spend Guardrails</a> · <a href="/docs/reference/run-tools">Run Tools</a> · <a href="/docs/operations/troubleshooting">Troubleshooting</a></p>`,59)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
